WITH filtered AS (SELECT *, ROUND(age * 100, 2) age_scaled, TRIM(city) clean_city FROM customers WHERE email IS NOT NULL) SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, country, MAX(age) AS max_age, COUNT(*) FILTER (WHERE segment = 'Consumer') AS consumer_rows, COUNT_IF(city = 'Singapore') AS singapore_events FROM filtered GROUP BY DATE_TRUNC('MONTH', signup_date), country HAVING COUNT(*) FILTER (WHERE segment = 'Consumer') >= 1;
